window.docContents[54].resolve({"/External-Cross-References/#PropertyKindCalculus-Blueprint--External-Cross-References":{"contents":"This work formalizes Dybkær's Ontology on Property and aligns its concepts with\nthe International Vocabulary of Metrology (VIM). The correspondence is recorded\nas typed, declaration-indexed metadata — two attributes, @[dybkaer …] and\n@[vim4 …], attached to the declarations of the core spine — so the two index\ntables below are generated from the source, not maintained by hand. Each row\nmaps an external locus to the external term and to this work's declaration, linked\nto its definition in this blueprint. Only locators are recorded; no normative text\nfrom either copyrighted source is reproduced.\n\n\n\n\n\n","context":"PropertyKindCalculus Blueprint","header":"24. External Cross-References","id":"/External-Cross-References/#PropertyKindCalculus-Blueprint--External-Cross-References"},"/ISO___IEC-80000-___-The-Standards-Catalogue/#PropertyKindCalculus-Blueprint--ISO___IEC-80000-___-The-Standards-Catalogue":{"contents":"The quantity-kinds and units specified here are grounded against the international\nstandard series ISO/IEC 80000, Quantities and units. That series is licensed\nand copyrighted: no normative content from it is reproduced in this work. What is\nrecorded is the citable identity of each part — body, number, part, edition, and\npublication date — so that every catalogued quantity-kind or unit can name its\nexact source. This chapter specifies that references layer; the chapters that\nfollow specify one part's quantity-kinds and units at a time, each added as\ncoverage of that part becomes available.\n\n\n\n","context":"PropertyKindCalculus Blueprint","header":"12. ISO/IEC 80000 — The Standards Catalogue","id":"/ISO___IEC-80000-___-The-Standards-Catalogue/#PropertyKindCalculus-Blueprint--ISO___IEC-80000-___-The-Standards-Catalogue"}});